const releaseText=String.raw`PASTE_THE_EXACT_LAB_7_RELEASE_METADATA_JSON_HERE`;
if(releaseText.startsWith('PASTE_')) throw new Error('Paste the exact release-metadata.json.');
return [{json:JSON.parse(releaseText)}];

const x=$input.first().json,m=x.package_manifest; const blockers=[]; if(x.run_id!=='HB-001') blockers.push('run_id_mismatch'); if(x.package_version!=='release-v1') blockers.push('package_version_mismatch'); if(x.privacy_status!=='private'||x.public_release_allowed!==false) blockers.push('unsafe_visibility'); if(x.contains_synthetic_media!==true) blockers.push('synthetic_disclosure_required'); for(const k of ['title','description','caption_path','video_path','rights_evidence_path','package_owner','package_manifest_path','package_sha256','final_review_approval_path','final_review_approval_sha256']) if(!x[k]) blockers.push(`missing_${k}`);
if(!m||m.run_id!==x.run_id||m.package_version!==x.package_version||m.title!==x.title||m.description!==x.description||m.privacy_status!==x.privacy_status||m.contains_synthetic_media!==x.contains_synthetic_media||m.package_owner!==x.package_owner||m.video?.path!==x.video_path||m.captions?.path!==x.caption_path||m.rights_manifest?.path!==x.rights_evidence_path) blockers.push('package_manifest_mismatch');
const review=m?.final_review_approval; if(!review||review.path!==x.final_review_approval_path||review.sha256!==x.final_review_approval_sha256||review.decision!=='APPROVED_FOR_PRIVATE_RELEASE_PACKAGE'||review.scope!=='private release package only; no public posting'||review.reviewed_video_sha256!==m?.video?.sha256) blockers.push('final_review_approval_invalid');
const previews=m?.platform_previews; if(previews?.youtube?.privacyStatus!=='private'||previews?.youtube?.containsSyntheticMedia!==true||previews?.youtube?.execute!==false||previews?.tiktok?.privacy_level!=='SELF_ONLY'||previews?.tiktok?.is_aigc!==true||previews?.tiktok?.source!=='FILE_UPLOAD'||!Number.isInteger(previews?.tiktok?.video_size)||previews?.tiktok?.chunk_size!==previews?.tiktok?.video_size||previews?.tiktok?.total_chunk_count!==1||previews?.tiktok?.execute!==false) blockers.push('platform_preview_schema_invalid');
let approvalValid=false; if(x.human_decision==='approve_private_dry_run'){const expires=Date.parse(x.approval_expires_at); approvalValid=!!x.approval_scope&&x.approval_package_sha256===x.package_sha256&&Number.isFinite(expires)&&expires>Date.now(); if(!approvalValid) blockers.push('approval_hash_or_expiry_invalid');}
let status='awaiting_human_approval'; if(x.human_decision==='deny') status='denied'; else if(x.human_decision==='approve_private_dry_run'&&blockers.length===0&&approvalValid) status='dry_run_ready'; else if(blockers.length&&x.human_decision!=='deny') status='blocked';
return [{json:{run_id:x.run_id,package_version:x.package_version,package_sha256:x.package_sha256,status,blockers,requested_visibility:'private',approval_expires_at:x.approval_expires_at||null,idempotency_key:`${x.run_id}-${x.package_version}-${String(x.package_sha256).slice(0,16)}`,platform_previews:previews||null,publish_allowed:false,external_action_count:0}}];
